import { expect, expectStatus, test } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ as: "member" });
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  // The sample certificate expires in 2027, so write one that expired yesterday.
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const expiredCertificate = [
    "Insurer: Harbor Mutual",
    "Policy Number: HM-55-1290",
    "Coverage Amount: $2,000,000",
    `Expiry Date: ${yesterday}`,
    "",
  ].join("\n");
  const certificate = await expectStatus<{ id: string }>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "insurance_certificate.txt", mimeType: "text/plain", buffer: Buffer.from(expiredCertificate) },
      },
    }),
    201,
  );
  // Wait for extraction of all three documents before submitting.
  await expect
    .poll(
      async () =>
        (await expectStatus<{ status: string }[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200)).map(
          (d) => d.status,
        ),
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const extraction = await factory.extraction(certificate.id, "reviewer");

  // Act
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  // Re-read the stored state: an expired certificate must not have been approved.
  expect((await factory.extraction(certificate.id, "reviewer")).status, "expired certificate stays pending").toBe(
    "pending_review",
  );
});
